program Sieve;
{$mode objfpc}{$H+}
const
  Max = 30;
var
  Composite: array[2..Max] of Boolean;
  P, Q: Integer;
begin
  for P := 2 to Max do Composite[P] := False;
  for P := 2 to Max do
    if not Composite[P] then
    begin
      Write(P, ' ');
      Q := P * P;
      while Q <= Max do
      begin
        Composite[Q] := True;
        Q := Q + P;
      end;
    end;
  WriteLn;
end.
